### Python

```python
import sys

def kadane(a, l, r):
	# 计算 a[l..r] 的最大子段和（l、r 为闭区间）
	cur = -10**18
	best = -10**18
	for i in range(l, r + 1):
		if cur < 0:
			cur = a[i]
		else:
			cur += a[i]
		if cur > best:
			best = cur
	return best

def main():
	data = list(map(int, sys.stdin.read().strip().split()))
	t = data[0]
	idx = 1
	out = []
	for _ in range(t):
		n = data[idx]; idx += 1
		a = data[idx:idx+n]; idx += n
		S = sum(a)
		# 前 n-1 段与后 n-1 段上的最大子段和
		left = kadane(a, 0, n - 2)
		right = kadane(a, 1, n - 1)
		out.append("Yes" if max(left, right) >= S else "No")
	print("\n".join(out))

if __name__ == "__main__":
	main()
```

### Java

```java
import java.io.*;
import java.util.*;

public class Main {
	static long kadane(int[] a, int l, int r) {
		// 计算 a[l..r] 的最大子段和
		long cur = Long.MIN_VALUE / 4;
		long best = Long.MIN_VALUE / 4;
		for (int i = l; i <= r; i++) {
			if (cur < 0) cur = a[i];
			else cur += a[i];
			if (cur > best) best = cur;
		}
		return best;
	}

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		StringBuilder sb = new StringBuilder();
		while (T-- > 0) {
			int n = sc.nextInt();
			int[] a = new int[n];
			long S = 0;
			for (int i = 0; i < n; i++) {
				a[i] = sc.nextInt();
				S += a[i];
			}
			long left = kadane(a, 0, n - 2);
			long right = kadane(a, 1, n - 1);
			sb.append(Math.max(left, right) >= S ? "Yes" : "No").append('\n');
		}
		System.out.print(sb.toString());
	}
}
